CREATE TABLE evaluation_public_calls(id uuid PRIMARY KEY,source_id text NOT NULL,source_version integer NOT NULL,kind text NOT NULL CHECK(kind IN ('media-caption','event-extraction')),provider text NOT NULL,model text NOT NULL,instructions text NOT NULL,input text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status text NOT NULL CHECK(status IN ('running','succeeded','failed')),raw_output text,text_output text,outcome text NOT NULL DEFAULT 'awaiting-provider', FOREIGN KEY(source_id,source_version) REFERENCES discovery_versions(item_id,version));
CREATE INDEX evaluation_public_source ON evaluation_public_calls(source_id,started_at DESC);
CREATE TABLE evaluation_public_views(id text PRIMARY KEY,source_id text NOT NULL,source_version integer NOT NULL,captured_at timestamptz NOT NULL DEFAULT now(),payload jsonb NOT NULL,FOREIGN KEY(source_id,source_version) REFERENCES discovery_versions(item_id,version));
CREATE INDEX evaluation_views_page ON evaluation_public_views(captured_at DESC,source_id);
CREATE TRIGGER evaluation_view_immutable BEFORE UPDATE OR DELETE ON evaluation_public_views FOR EACH ROW EXECUTE FUNCTION prevent_discovery_revision_mutation();
CREATE OR REPLACE FUNCTION protect_evaluation_call() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status<>'running' THEN RAISE EXCEPTION 'Completed evaluation calls are immutable'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER evaluation_call_immutable BEFORE UPDATE OR DELETE ON evaluation_public_calls FOR EACH ROW EXECUTE FUNCTION protect_evaluation_call();
ALTER TABLE account_consent_heads DROP CONSTRAINT account_consent_heads_purpose_check;
ALTER TABLE account_consent_heads ADD CONSTRAINT account_consent_heads_purpose_check CHECK(purpose IN ('external-ai-private-context','private-ai-history','reading-personalization','scheduled-record-reviews','automatic-material-checks'));
CREATE TABLE private_ai_history(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,provider text NOT NULL,model text NOT NULL,instructions text NOT NULL,input text NOT NULL,raw_output text,text_output text,status text NOT NULL CHECK(status IN ('running','succeeded','failed')),outcome text NOT NULL DEFAULT 'awaiting-provider',created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,consent_version integer NOT NULL);
CREATE INDEX private_ai_history_owner ON private_ai_history(user_id,created_at DESC);
CREATE INDEX private_ai_history_expiry ON private_ai_history(expires_at);
CREATE TABLE evaluation_public_compositions(id text PRIMARY KEY,source_id text NOT NULL,source_version integer NOT NULL,item jsonb NOT NULL,asset_id uuid NOT NULL REFERENCES discovery_media(id),image_attempt_id uuid,image_hash text,captured_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(source_id,source_version) REFERENCES discovery_versions(item_id,version));
CREATE INDEX evaluation_composition_source ON evaluation_public_compositions(source_id,captured_at DESC);
CREATE TRIGGER evaluation_composition_immutable BEFORE UPDATE OR DELETE ON evaluation_public_compositions FOR EACH ROW EXECUTE FUNCTION prevent_discovery_revision_mutation();
